UPDATE proactive_prompt_events
SET status = #{status}, updated_at = #{updatedAt}
WHERE user_id = #{userId} AND fingerprint = #{fingerprint}
  AND status NOT IN ('answered')

UPDATE proactive_prompt_events
SET status = #{status}, updated_at = #{updatedAt}
WHERE user_id = #{userId}
  AND prompt_id = #{promptId}
  AND prompt_date = #{promptDate}
  AND status NOT IN ('answered')

mapper.select:
SELECT id, user_id, prompt_date, prompt_id, fingerprint, source, prompt_text,
       related_date, status, created_at, updated_at
FROM proactive_prompt_events
WHERE user_id = #{userId}
  AND fingerprint = #{fingerprint}
  AND prompt_date = #{promptDate}
LIMIT 1
